B.oM=A.a(s([B.uB,B.nC]),t.O)
B.ajU=new A.eX("Em k\xeejan daneyan kom dikin?","Leyar ten\xea daney\xean ji bo l\xeestik \xfb hesab\xea p\xeaw\xeest in dipar\xeaze:\n\u2022 Agahiy\xean hesab \xfb nasnamey\xea \u2014 ji bo t\xeaketina anon\xeem, Google an e-posta \xfb senkron\xeezekirina p\xea\u015fve\xe7\xfbn\xea.\n\u2022 Agahiy\xean prof\xeel\xea \u2014 nav\xea l\xeestikvan, avatar/prof\xeel \xfb nasnameya nav l\xeestik\xea.\n\u2022 Daney\xean l\xeestik\xea \u2014 p\xfban, p\xea\u015fve\xe7\xfbna rojane, rozet, tabloya p\xfbanan, tevger \xfb d\xeeroka l\xeestik\xea.\n\u2022 Daney\xean gelek-l\xeestikvan \u2014 vexwendin, ode, hevr\xeaz\xee, dora l\xeestik\xea \xfb encam.\n\u2022 Peyam\xean chat\xea \u2014 peyam\xean di navbera l\xeestikvan\xean heman ma\xe7\xea de \xfb l\xeakol\xeena xerab-bikaran\xeen\xea.\n\u2022 Token a agahdariyan \u2014 ten\xea dema dest\xfbr hatiye day\xeen.\n\u2022 Daney\xean xelet\xee, performans \xfb bikaran\xeen\xea \u2014 ji bo \xe7aksazkirin \xfb ba\u015ftirkirina sepan\xea.")
B.ajV=new A.eX("Em k\xeejan daneyan kom nakin?","Em cih\xea rast, t\xeakil\xee/rehber, SMS, tomar\xean bang\xea, kamera, m\xeekrofon, daney\xean tendurist\xee, agahiy\xean daray\xee, nasnameya ferm\xee, w\xeane an salnamey\xea naxwazin.")
B.ajT=new A.eX("Daney\xean te \xe7awa t\xea bikaran\xeen?","Daneyan ji bo xebitandina l\xeestik\xea, senkron\xeezekirina hesab\xea, vexwendin \xfb chat\xea, agahdariyan, ewleh\xee, l\xeakol\xeena xerab-bikaran\xeen\xea \xfb \xe7aksazkirina xelet\xee/performance t\xea bikaran\xeen.")
B.ajQ=new A.eX("Daney\xean te bi k\xea re t\xea parvekirin?","Leyar ji bo binesaziy\xea xizmet\xean Google Firebase bikar t\xeene: Firebase Authentication, Cloud Firestore, Firebase Cloud Messaging, Firebase Crashlytics \xfb Firebase Analytics. Daney\xean te ji bo reklam\xea nay\xean firotin \xfb bi tor\xean reklam\xea, broker\xean daneyan an parg\xeedaniy\xean bazariy\xea re nay\xean parvekirin.")
B.ajN=new A.eX("Ewleh\xee","Veguhestina daneyan bi gir\xeadan\xean ewle t\xea kirin. Nasnamekirin, r\xeagez\xean gih\xee\u015ftin\xea \xfb kontrol\xean ewlehiy\xea y\xean Firebase t\xeane bikaran\xeen. L\xea ti r\xeabazeke internet\xea bi temam\xee b\xea xeter n\xeene.")
B.ak_=new A.eX("Hilan\xeen \xfb j\xeabirina daneyan","Hesab, p\xea\u015fve\xe7\xfbna l\xeestik\xea, p\xfban, vexwendin, chat \xfb daney\xean t\xeakildar heta hesab akt\xeef be dikarin werin hilan\xeen. Ji bo j\xeabirina hesab an daney\xean kesane ji nav sepan\xea an ji smnfrt@gmail.com re daxwaz bi\u015f\xeene.")
B.ajM=new A.eX("Ve\u015fariya zarokan","Leyar zarok\xean di bin 13 saliy\xea de ne armanc dike. Ger em f\xear bibin ku bikarh\xeanerek di bin 13 saliy\xea de daneyan dixe, em wan daneyan j\xea dibin.")
B.ajX=new A.eX("N\xfbkirin\xean pol\xeet\xeekay\xea","Ev pol\xeet\xeeka dikare were n\xfbkirin. Di guhertin\xean gir\xeeng de em dikarin di nav sepan\xea an li ser r\xfbpela pol\xeet\xeekay\xea agahdar\xee bidin.")
B.ajP=new A.eX("T\xeakil\xee","Ji bo pirs\xean xwe: smnfrt@gmail.com")
